<?php
declare(strict_types=1);
require_once __DIR__.'/NativePortalProfile.php';
require_once __DIR__.'/NativePortalPresentation.php';
require_once __DIR__.'/NativePortalVerificationMail.php';
/** Original Clients actions and template; admission remains the central finite route gate. */
final class NativePortalProfileHttp
{
 private NativePortalProfile$writer;private int$issuer;private string$secret;
 public function __construct(private$ci){if(!PortalRequestScope::sealedFor($ci)||strtolower($ci->router->fetch_class())!=='clients'||!in_array(strtolower($ci->router->fetch_method()),['profile','remove_profile_image','company'],true)||!in_array($ci->input->method(true),['GET','HEAD','POST'],true))throw new DomainException('native_portal_context_required');$this->issuer=PortalRequestScope::issuerId();$this->secret=$ci->config->item('encryption_key');$identity=(new NativePortalIdentity($ci->db,db_prefix(),$this->secret))->current($ci->session,$this->issuer);if(!$identity)throw new DomainException('native_portal_profile_denied');$this->writer=new NativePortalProfile($ci->db,db_prefix(),$this->secret,$this->issuer,$identity['binding']);}
 private function value(string$key):string{$v=$this->ci->input->post($key,false);if($v===null)return'';if(!is_string($v))throw new DomainException('native_portal_profile_invalid');return$v;}
 private function decrypt(string$value):string{$this->ci->load->library('encryption');$plain=$this->ci->encryption->decrypt($value);if(!is_string($plain))throw new RuntimeException('issuer_portal_decryption_failed');return$plain;}
 private function hasher(){require_once APPPATH.'third_party/phpass.php';return new PasswordHash(PHPASS_HASH_STRENGTH,PHPASS_HASH_PORTABLE);}
 public function profile():void{
  if($this->ci->input->method(true)==='POST'){
   PortalRequestScope::assertMutation($this->ci);$revision=$this->value('native_profile_revision');$profile=$this->value('profile');$password=$this->value('change_password');if(($profile==='')===($password===''))throw new DomainException('native_portal_profile_invalid');
   if($profile!==''){$values=[];foreach(['firstname','lastname','email','phonenumber','title','direction','invoice_emails','credit_note_emails','estimate_emails','contract_emails','ticket_emails','project_emails','task_emails']as$key){$v=$this->ci->input->post($key,false);if($v!==null)$values[$key]=$v;}$custom=$this->ci->input->post('custom_fields',false);if($custom!==null&&(!is_array($custom)||array_diff(array_keys($custom),['contacts'])))throw new DomainException('native_portal_profile_invalid');$values['custom_fields']=$custom['contacts']??[];
    $bytes=null;$upload=$_FILES['profile_image']??null;if($upload!==null&&($upload['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){if(!is_array($upload)||($upload['error']??-1)!==UPLOAD_ERR_OK||!is_string($upload['tmp_name']??null)||!is_uploaded_file($upload['tmp_name'])||!is_int($upload['size']??null)||$upload['size']>NativeCompanyContactImage::MAX_BYTES)throw new DomainException('company_contact_image_invalid');$bytes=file_get_contents($upload['tmp_name']);if(!is_string($bytes)||strlen($bytes)!==$upload['size'])throw new DomainException('company_contact_image_invalid');}
    $mail=new NativePortalVerificationMail($this->ci->db,db_prefix(),$this->secret);$result=$this->writer->saveContact($revision,$values,fn($issuer,$contact,$writer)=>$mail->queueProfileInOwned($issuer,$contact,$writer,$this->ci->config->item('base_url'),fn($v)=>$this->decrypt($v)),$mail->tables(),$bytes);
   }else{$hasher=$this->hasher();$result=$this->writer->changePassword($revision,$this->value('oldpassword'),$this->value('newpassword'),$this->value('newpasswordr'),[$hasher,'CheckPassword'],[$hasher,'HashPassword']);}
   (new NativePortalIdentity($this->ci->db,db_prefix(),$this->secret))->establish($this->ci->session,$this->issuer,$result['binding']);set_alert('success',_l($profile!==''?'clients_profile_updated':'client_password_changed'));redirect(NativePortalPresentation::url('clients/profile'),'location',303);return;
  }
  $state=$this->writer->read();$image=$this->writer->avatar();$this->ci->native_portal_profile=$this->writer;$this->ci->data(['title'=>_l('clients_profile_heading'),'contact'=>(object)$state['contact'],'native_profile_revision'=>$state['revision'],'native_profile_permissions'=>$state['permissions'],'native_profile_image'=>$image?'data:'.$image['mime'].';base64,'.base64_encode($image['content']):null]);$this->ci->view('profile');$this->ci->layout();
 }
 public function remove():void{PortalRequestScope::assertMutation($this->ci);$this->writer->saveAvatar($this->value('native_profile_revision'),null);redirect(NativePortalPresentation::url('clients/profile'),'location',303);}
 public function company():void{
  if($this->ci->input->method(true)==='POST'){PortalRequestScope::assertMutation($this->ci);if($this->value('company_form')==='')throw new DomainException('native_portal_profile_invalid');$values=[];foreach(['company','vat','phonenumber','website','country','city','address','zip','state','default_language','billing_street','billing_city','billing_state','billing_zip','billing_country','shipping_street','shipping_city','shipping_state','shipping_zip','shipping_country']as$key){$v=$this->ci->input->post($key,false);if($v!==null)$values[$key]=$v;}$custom=$this->ci->input->post('custom_fields',false);if($custom!==null&&(!is_array($custom)||array_diff(array_keys($custom),['customers'])))throw new DomainException('native_portal_profile_invalid');$values['custom_fields']=$custom['customers']??[];$this->writer->saveCompany($this->value('native_company_revision'),$values);set_alert('success',_l('clients_profile_updated'));redirect(NativePortalPresentation::url('clients/company'),'location',303);return;}
  $state=$this->writer->company();$this->ci->native_portal_profile=$this->writer;$this->ci->data(['title'=>_l('client_company_info'),'client'=>(object)$state['client'],'contact'=>(object)$this->writer->read()['contact'],'native_company_revision'=>$state['revision'],'native_company_profile_policy'=>$state['policy'],'native_company_profile_countries'=>IssuerStorage::query($this->ci->db,'SELECT country_id,short_name FROM '.db_prefix().'countries ORDER BY short_name,country_id')->result_array(),'native_company_profile_languages'=>NativePortalPresentation::languages()]);$this->ci->view('company_profile');$this->ci->layout();
 }

}
